import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    # Determine relocation status
    has_relocation = data.get('RELOCATION_PACKAGE') == 'Yes'

    def replace_in_para(para, replacements):
        text = para.text
        new_text = text
        for key, val in replacements.items():
            placeholder = '{{' + key + '}}'
            if placeholder in new_text:
                new_text = new_text.replace(placeholder, str(val))

        if new_text != text:
            # Preserve formatting by updating the first run and clearing others
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.add_run(new_text)

    # 1. Handle Conditional Sections at Paragraph Level
    # This is a bit tricky if markers are in different paragraphs.
    # But usually they are in the same or surrounding ones.

    in_relocation_block = False
    paragraphs_to_remove = []

    for para in doc.paragraphs:
        text = para.text

        if '{{IF_RELOCATION}}' in text:
            in_relocation_block = True
            # Remove the marker
            para.text = text.replace('{{IF_RELOCATION}}', '')
            if not has_relocation:
                paragraphs_to_remove.append(para)
            continue

        if '{{END_IF_RELOCATION}}' in text:
            in_relocation_block = False
            # Remove the marker
            para.text = text.replace('{{END_IF_RELOCATION}}', '')
            if not has_relocation:
                paragraphs_to_remove.append(para)
            continue

        if in_relocation_block and not has_relocation:
            paragraphs_to_remove.append(para)

    # If we need to remove paragraphs (when has_relocation is False)
    # Actually the instruction says: "keep those content if RELOCATION_PACKAGE is set to Yes but remove the IF/END_IF markers etc for final offer letter."
    # So if it is Yes, I just remove markers (already done above by replacing with empty string).
    # If it was No, I would remove the content.

    # Let's refine the logic to handle markers that might be in the same paragraph as content
    for para in doc.paragraphs:
        if not has_relocation:
            # If No, and it's marked as to be removed
            if para in paragraphs_to_remove:
                para.text = ''

        # Replace all other placeholders
        replace_in_para(para, data)

    # Process tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para, data)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Headers/Footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_para(para, data)
        for para in section.footer.paragraphs:
            replace_in_para(para, data)

    doc.save(output_path)

if __name__ == "__main__":
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

